CREATE TABLE `${project}.${dataset}.Person` (id INT64, name STRING);
INSERT `${project}.${dataset}.Person` VALUES (1, 'Alex'), (2, 'Dana'), (3, 'Lee');
CREATE TABLE `${project}.${dataset}.Knows` (id INT64, src INT64, dst INT64);
INSERT `${project}.${dataset}.Knows` VALUES (10, 1, 2), (11, 2, 1), (12, 1, 1), (13, 1, 2);
CREATE PROPERTY GRAPH `${project}.${dataset}.FinGraph`
NODE TABLES (`${project}.${dataset}.Person` AS Person KEY(id))
EDGE TABLES (`${project}.${dataset}.Knows` AS Knows KEY(id) SOURCE KEY(src) REFERENCES Person(id) DESTINATION KEY(dst) REFERENCES Person(id));

